// Background library for the Music Video live visualizer.
//
// Two kinds of clip:
//  • kind:'image' — bundled generative backgrounds (public/bg/generative/*.jpg),
//    generated by scripts/gen-bg-images.mjs. Real, detailed, work offline NOW.
//  • kind:'video' — the curated nature clips (Aerial/Beach/Mountains/Animals/City)
//    that STREAM online from a CDN/R2 base (NEXT_PUBLIC_BG_CDN) as <id>.mp4, with a
//    small poster cached offline at public/bg/previews/<id>.jpg. Until you host a
//    clip it shows its poster / a gradient tint.
//
// Adding a clip = add a row here (no code change). Hosting the nature clips + a CSP
// media-src for the CDN are the ops step; the bundled images need neither.

export interface BgClip {
  id: string
  category: BgCategory
  title: string
  kind: 'image' | 'video'
  preview: string   // thumbnail / poster (same-origin, cached offline)
  src: string       // full asset (image is same-origin; video streams from the CDN)
  tint: string      // gradient shown until the asset loads (and if it 404s)
}

export const BG_CATEGORIES = ['Patterns', 'Aerial', 'Beach', 'Mountains', 'Animals', 'City', 'Ambient'] as const
export type BgCategory = typeof BG_CATEGORIES[number]

const CDN = (process.env.NEXT_PUBLIC_BG_CDN || '').replace(/\/$/, '')

