export const BG_LIBRARY: BgClip[] = [
  ...GENERATIVE.map(g => ({
    id: g.id, category: 'Patterns' as BgCategory, title: g.title, kind: 'image' as const,
    preview: `/bg/generative/${g.id}.jpg`, src: `/bg/generative/${g.id}.jpg`, tint: g.tint,
  })),
  ...NATURE.map(c => ({
    ...c, kind: 'video' as const,
    preview: `/bg/previews/${c.id}.jpg`, src: CDN ? `${CDN}/${c.id}.mp4` : `/bg/clips/${c.id}.mp4`,
  })),
]

export const clipsByCategory = (cat: BgCategory): BgClip[] => BG_LIBRARY.filter(c => c.category === cat)
export const clipById = (id: string): BgClip | undefined => BG_LIBRARY.find(c => c.id === id)
